export default [["q-fcps-pat4-01","A child has recurrent bacterial infections, delayed umbilical cord separation and marked neutrophilia without pus formation. The defect is in:",["CD18 integrin (leukocyte adhesion)","NADPH oxidase","Myeloperoxidase","Lysosomal trafficking regulator"],"Leukocyte adhesion deficiency type 1 is absent beta-2 integrin, so neutrophils cannot adhere and emigrate and stay in the blood."],["q-fcps-pat4-02","Which complement component deficiency predisposes to recurrent Neisseria infections?",["Terminal components C5 to C9","C1 esterase inhibitor","C3","Decay-accelerating factor"],"The membrane attack complex is needed to lyse Neisseria, so deficiency gives recurrent meningococcal and gonococcal infection."],["q-fcps-pat4-03","Hereditary angioedema is caused by deficiency of:",["C1 esterase inhibitor","C3","C5","Factor H"],"Uncontrolled bradykinin production causes swelling without urticaria, and C4 is low."],["q-fcps-pat4-04","Which cell type is the main source of granulation tissue collagen in wound healing?",["Fibroblasts","Macrophages","Neutrophils","Mast cells"],"Fibroblasts lay down type III collagen first, which is later replaced by type I during remodelling."],["q-fcps-pat4-05","Which collagen type is deposited first in a healing wound?",["Type III","Type I","Type II","Type IV"],"Early granulation tissue contains type III collagen, and it is replaced by stronger type I collagen over weeks."],["q-fcps-pat4-06","A patient has a sudden onset of dyspnoea, petechiae and confusion 48 hours after a femur fracture. The most likely diagnosis is:",["Fat embolism","Pulmonary thromboembolism","Air embolism","Amniotic fluid embolism"],"Fat embolism syndrome presents classically 24 to 72 hours after long bone fracture with respiratory failure, neurological signs and petechiae."],["q-fcps-pat4-07","A woman collapses during labour and develops hypoxia and disseminated intravascular coagulation. Which condition is likely?",["Amniotic fluid embolism","Pulmonary thromboembolism","Septic shock","Fat embolism"],"Fetal squamous cells and mucin enter the maternal circulation and trigger an anaphylactoid reaction with DIC."],["q-fcps-pat4-08","A paradoxical embolus passes from a leg vein to the brain through a:",["Patent foramen ovale","Patent ductus arteriosus only","Mitral stenosis","Pulmonary shunt"],"A right-to-left shunt allows a venous thrombus to enter the systemic arterial circulation and cause a stroke."],["q-fcps-pat4-09","In the stages of shock, which finding is characteristic of the initial non-progressive stage?",["Compensatory tachycardia and vasoconstriction","Irreversible cell damage","Anuria","Metabolic acidosis with multiorgan failure"],"In the early compensated stage, reflex mechanisms maintain perfusion of vital organs."],["q-fcps-pat4-10","Which tumour suppressor gene is mutated in familial adenomatous polyposis?",["APC","RB","p53","NF1"],"APC mutations activate the Wnt pathway, producing hundreds of colorectal polyps with nearly 100 percent progression to cancer."],["q-fcps-pat4-11","Which oncogene is amplified in some breast cancers and is the target of trastuzumab?",["HER2 (ERBB2)","MYC","RAS","BCL2"],"HER2 amplification gives a more aggressive tumour that responds to trastuzumab."],["q-fcps-pat4-12","Burkitt lymphoma involves overexpression of which gene?",["MYC","BCL2","Cyclin D1","RAS"],"The t(8;14) translocation places MYC under the immunoglobulin heavy chain promoter."],["q-fcps-pat4-13","Follicular lymphoma is characterised by which translocation?",["t(14;18) with BCL2 overexpression","t(8;14)","t(11;14)","t(9;22)"],"BCL2 overexpression blocks apoptosis, causing an indolent lymphoma of germinal centre B cells."],["q-fcps-pat4-14","Mantle cell lymphoma is associated with:",["t(11;14) and cyclin D1 overexpression","t(14;18)","t(8;14)","t(15;17)"],"Cyclin D1 overexpression drives progression through the G1-S checkpoint."],["q-fcps-pat4-15","Acute promyelocytic leukaemia is characterised by:",["t(15;17) and Auer rods, with a risk of DIC","t(9;22) and basophilia","t(8;21) only","Smudge cells"],"The PML-RARA fusion blocks differentiation, and treatment with all-trans retinoic acid induces maturation."],["q-fcps-pat4-16","Which neoplasm is associated with the JAK2 V617F mutation?",["Polycythaemia vera","Chronic myeloid leukaemia","Hairy cell leukaemia","Multiple myeloma"],"JAK2 V617F is found in most polycythaemia vera and in many cases of essential thrombocythaemia and primary myelofibrosis."],["q-fcps-pat4-17","Which tumour marker is used to monitor ovarian epithelial cancer?",["CA-125","CA 19-9","CEA","PSA"],"CA-125 is raised in epithelial ovarian cancer but is not specific because it can rise in endometriosis and menstruation."],["q-fcps-pat4-18","Which tumour marker is used to follow colorectal cancer recurrence?",["CEA","AFP","CA-125","Calcitonin"],"Carcinoembryonic antigen is used mainly for monitoring after resection rather than for screening."],["q-fcps-pat4-19","A man with a testicular mass has a markedly raised beta-hCG and a normal AFP. The tumour is most likely:",["Choriocarcinoma","Yolk sac tumour","Mature teratoma","Leydig cell tumour"],"Choriocarcinoma gives very high beta-hCG, while yolk sac tumours produce AFP. Pure seminomas may produce only mildly raised hCG."],["q-fcps-pat4-20","Which paraneoplastic syndrome is characteristic of squamous cell carcinoma of the lung?",["Hypercalcaemia from PTHrP","SIADH","Cushing syndrome","Lambert-Eaton syndrome"],"Squamous cancers secrete PTH-related peptide. Small cell cancers secrete ADH and ACTH."],["q-fcps-pat4-21","Which carcinogen is most strongly associated with mesothelioma?",["Asbestos","Silica","Coal dust","Beryllium"],"Asbestos exposure causes pleural plaques, asbestosis, lung carcinoma and malignant mesothelioma after a latent period of decades."],["q-fcps-pat4-22","Aromatic amines such as aniline dyes cause which cancer?",["Urothelial (bladder) carcinoma","Hepatic angiosarcoma","Lung adenocarcinoma","Nasal adenocarcinoma"],"Occupational exposure in dye and rubber workers is a classic cause of bladder carcinoma, as is smoking."],["q-fcps-pat4-23","Vinyl chloride exposure is associated with:",["Hepatic angiosarcoma","Mesothelioma","Cholangiocarcinoma","Bladder carcinoma"],"Angiosarcoma of the liver is a rare tumour linked to vinyl chloride, arsenic and thorotrast."],["q-fcps-pat4-24","The oncogenic action of high-risk human papillomavirus involves:",["E6 degrading p53 and E7 inactivating RB","Insertion of the virus near MYC","Activating RAS","Blocking BCL2"],"E6 promotes degradation of p53 and E7 binds RB, allowing the cell to cycle unchecked, which leads to cervical intraepithelial neoplasia."],["q-fcps-pat4-25","Epstein-Barr virus is associated with all of the following EXCEPT:",["Hepatocellular carcinoma","Nasopharyngeal carcinoma","Burkitt lymphoma","Post-transplant lymphoproliferative disease"],"Hepatocellular carcinoma is linked to hepatitis B and C and aflatoxin, not EBV."],["q-fcps-pat4-26","Gastric MALT lymphoma may regress after treatment of:",["Helicobacter pylori","Hepatitis C","Epstein-Barr virus","Cytomegalovirus"],"Chronic H. pylori infection drives B cell proliferation, and eradication often induces remission in early disease."],["q-fcps-pat4-27","HLA-B27 is associated with:",["Ankylosing spondylitis","Rheumatoid arthritis","Type 1 diabetes","Multiple sclerosis"],"HLA-B27 is associated with the seronegative spondyloarthropathies, including reactive arthritis and psoriatic arthritis."],["q-fcps-pat4-28","HLA-DR3 and DR4 are associated with:",["Type 1 diabetes mellitus","Ankylosing spondylitis","Goodpasture syndrome","Narcolepsy"],"Both haplotypes increase risk of autoimmune destruction of pancreatic beta cells."],["q-fcps-pat4-29","Hyperacute rejection of a transplanted kidney is mediated by:",["Preformed antibodies against donor antigens","Sensitised T cells","Immune complex deposition after months","Chronic vascular intimal thickening"],"Preformed anti-ABO or anti-HLA antibodies cause thrombotic occlusion of the graft vessels within minutes to hours."],["q-fcps-pat4-30","Chronic rejection of a kidney graft is characterised by:",["Concentric intimal fibrosis of graft arteries","Neutrophilic infiltration of the vessels","Thrombosis within hours","Cellular infiltrate with tubulitis only"],"Chronic allograft vasculopathy leads to gradual graft failure over months to years."],["q-fcps-pat4-31","Which type of amyloid is associated with long-standing rheumatoid arthritis and tuberculosis?",["AA amyloid derived from serum amyloid A","AL amyloid","Abeta amyloid","Beta-2 microglobulin amyloid"],"Secondary (reactive) amyloidosis arises from chronic inflammation and mainly affects the kidney, liver and spleen."],["q-fcps-pat4-32","AL amyloid is derived from:",["Immunoglobulin light chains","Serum amyloid A","Transthyretin","Calcitonin"],"Primary amyloidosis occurs in plasma cell dyscrasias such as multiple myeloma and affects the heart, kidney and tongue."],["q-fcps-pat4-33","A boy has recurrent bacterial infections from the age of 6 months with absent B cells and very low immunoglobulins of all classes. The mutation is in:",["Bruton tyrosine kinase","ADA","CD40 ligand","WAS protein"],"X-linked agammaglobulinaemia from BTK defects blocks B cell maturation, so the tonsils are small and patients have recurrent sinopulmonary infections."],["q-fcps-pat4-34","A boy with eczema, thrombocytopenia with small platelets and recurrent infections has:",["Wiskott-Aldrich syndrome","Bruton agammaglobulinaemia","DiGeorge syndrome","Hyper-IgM syndrome"],"It is an X-linked disorder of the WAS gene affecting cytoskeletal function of haematopoietic cells."],["q-fcps-pat4-35","A patient has HIV infection and a CD4 count of 80 per microlitre. Which infection is most likely to cause cerebral ring-enhancing lesions?",["Toxoplasma gondii","Cryptococcus neoformans","Cytomegalovirus","Mycobacterium avium complex"],"Reactivation of Toxoplasma cysts causes multiple ring-enhancing lesions in advanced HIV disease."],["q-fcps-pat4-36","Which karyotype is typical of Klinefelter syndrome?",["47,XXY","45,X","47,XYY","47,XXX"],"Klinefelter syndrome presents with tall stature, small firm testes, gynaecomastia and infertility."],["q-fcps-pat4-37","Turner syndrome is associated with:",["Coarctation of the aorta and streak ovaries","Pulmonary stenosis only","Tall stature","Elevated oestrogen"],"Patients with 45,X have short stature, webbed neck, primary amenorrhoea with raised FSH and bicuspid aortic valve."],["q-fcps-pat4-38","A tall man with arachnodactyly and aortic root dilatation has a defect in:",["Fibrillin-1","Type I collagen","Type III collagen","Elastin"],"Marfan syndrome results from FBN1 mutation with excess TGF-beta signalling. Complications include aortic dissection and ectopia lentis."],["q-fcps-pat4-39","Hereditary spherocytosis is best diagnosed by:",["Increased osmotic fragility with a negative direct Coombs test","Heinz bodies","Positive direct Coombs test","Ham test"],"Defects of spectrin or ankyrin make red cells spherical, so they are removed in the spleen. The Coombs test is negative."],["q-fcps-pat4-40","Heinz bodies and bite cells are seen in:",["G6PD deficiency","Hereditary spherocytosis","Sickle cell disease","Thalassaemia"],"Oxidative stress denatures haemoglobin, producing Heinz bodies, which the spleen removes as bite cells."],["q-fcps-pat4-41","Warm autoimmune haemolytic anaemia is typically mediated by:",["IgG antibodies","IgM antibodies","Cold agglutinins","Complement alone"],"IgG-coated red cells are cleared in the spleen. Cold agglutinin disease is IgM-mediated, with intravascular haemolysis in the cold."],["q-fcps-pat4-42","Paroxysmal nocturnal haemoglobinuria is caused by deficiency of:",["GPI-anchored proteins CD55 and CD59","Ankyrin","Spectrin","Glucose-6-phosphate dehydrogenase"],"PIGA mutation leads to complement-mediated lysis of red cells and a risk of venous thrombosis."],["q-fcps-pat4-43","Which finding is typical of aplastic anaemia?",["Pancytopenia with a hypocellular bone marrow","Pancytopenia with a hypercellular marrow","Isolated anaemia with reticulocytosis","Blasts in the blood"],"The marrow is replaced by fat. Causes include drugs, viral infections and idiopathic autoimmune destruction."],["q-fcps-pat4-44","Thrombotic thrombocytopenic purpura is caused by deficiency of:",["ADAMTS13","Factor VIII","von Willebrand factor","Glycoprotein Ib"],"Loss of ADAMTS13 leaves ultra-large von Willebrand multimers, so platelets aggregate in small vessels, causing microangiopathic haemolysis."],["q-fcps-pat4-45","Which laboratory finding is typical of von Willebrand disease?",["Prolonged bleeding time with normal platelet count","Low platelet count","Prolonged prothrombin time","Low fibrinogen"],"Defective platelet adhesion and secondary low factor VIII can prolong the aPTT, while the PT is normal."],["q-fcps-pat4-46","Which finding is characteristic of hypertrophic cardiomyopathy?",["Myocyte disarray with asymmetric septal hypertrophy","Dilated ventricles","Amyloid deposits","Granulomas"],"It is caused by sarcomere gene mutations such as beta-myosin heavy chain and is a leading cause of sudden death in young athletes."],["q-fcps-pat4-47","Silicosis predisposes to which infection?",["Tuberculosis","Aspergillosis","Legionella","Pneumocystis"],"Silica impairs macrophage function and increases the risk of tuberculosis. Eggshell calcification of hilar nodes is typical."],["q-fcps-pat4-48","Ferruginous bodies in the lung are characteristic of:",["Asbestosis","Silicosis","Coal workers' pneumoconiosis","Berylliosis"],"Asbestos fibres coated with haemosiderin appear as golden-brown beaded rods in lung tissue."],["q-fcps-pat4-49","Non-caseating granulomas with raised serum ACE and bilateral hilar lymphadenopathy in a young woman suggest:",["Sarcoidosis","Tuberculosis","Hodgkin lymphoma","Histoplasmosis"],"Sarcoidosis is a multisystem granulomatous disease that may cause hypercalcaemia through vitamin D activation."],["q-fcps-pat4-50","Hyaline membranes lining alveoli are typical of:",["Diffuse alveolar damage (ARDS)","Chronic bronchitis","Bronchiectasis","Asthma"],"Acute respiratory distress syndrome shows diffuse alveolar damage, with endothelial and epithelial injury and protein-rich exudate."],["q-fcps-pat4-51","Chronic bronchitis is defined clinically by cough with sputum for at least:",["3 months in each of 2 consecutive years","1 month in a year","6 weeks in total","1 year without remission"],"Pathology shows mucous gland hypertrophy, with an increased Reid index above 0.4."],["q-fcps-pat4-52","Skip lesions, cobblestone mucosa and a fistula in a patient with diarrhoea suggest:",["Crohn disease","Ulcerative colitis","Ischaemic colitis","Coeliac disease"],"Crohn disease is transmural and can affect any part of the gut, and it is associated with strictures and fistulae."],["q-fcps-pat4-53","Which feature favours ulcerative colitis over Crohn disease?",["Continuous mucosal inflammation starting in the rectum","Transmural inflammation","Non-caseating granulomas","Skip lesions"],"Ulcerative colitis is limited to the mucosa and submucosa, with crypt abscesses and a risk of toxic megacolon and primary sclerosing cholangitis."],["q-fcps-pat4-54","Which hepatitis virus is transmitted by the faecal-oral route and is particularly dangerous in pregnancy?",["Hepatitis E","Hepatitis B","Hepatitis C","Hepatitis D"],"Hepatitis E causes high mortality from fulminant hepatic failure in pregnant women, especially in the third trimester."],["q-fcps-pat4-55","Which hepatitis serological pattern indicates a vaccinated person?",["Anti-HBs positive only","HBsAg and anti-HBc positive","Anti-HBc IgM positive","HBeAg positive"],"Vaccination produces antibody to surface antigen alone, while natural infection also produces anti-HBc."],["q-fcps-pat4-56","A patient with chronic hepatitis B has a rising AFP and a liver mass. The most likely diagnosis is:",["Hepatocellular carcinoma","Cholangiocarcinoma","Haemangioma","Focal nodular hyperplasia"],"Cirrhosis from chronic hepatitis B or C is the main risk factor, though HBV can cause HCC without cirrhosis."],["q-fcps-pat4-57","In acute pancreatitis, which two causes are most common?",["Gallstones and alcohol","Hypertriglyceridaemia and trauma","Drugs and viral infection","ERCP and scorpion venom"],"Gallstones and alcohol together account for most cases in adults."],["q-fcps-pat4-58","A 55-year-old man has painless jaundice, a palpable gallbladder and weight loss. Courvoisier's law suggests:",["Malignant obstruction of the common bile duct","Gallstone obstruction of the common bile duct","Acute cholecystitis","Hepatitis"],"A palpable non-tender gallbladder with jaundice is more likely to be caused by cancer, since a gallbladder scarred by stones cannot distend."],["q-fcps-pat4-59","Nephrotic syndrome in an adult with a 'spike and dome' appearance on silver stain is:",["Membranous nephropathy","Minimal change disease","Focal segmental glomerulosclerosis","IgA nephropathy"],"Subepithelial immune deposits with basement membrane spikes occur in membranous nephropathy, associated with anti-PLA2R antibodies."],["q-fcps-pat4-60","Haematuria one to two days after an upper respiratory infection in a young man suggests:",["IgA nephropathy","Post-streptococcal glomerulonephritis","Minimal change disease","Alport syndrome"],"IgA nephropathy follows mucosal infection within days, whereas post-streptococcal glomerulonephritis follows 1 to 3 weeks later."],["q-fcps-pat4-61","Hearing loss, haematuria and lens abnormalities in a family are characteristic of:",["Alport syndrome","Fabry disease","Thin basement membrane disease","Goodpasture syndrome"],"Alport syndrome is a defect of type IV collagen, with basket-weave basement membranes."],["q-fcps-pat4-62","Clear cell renal carcinoma is associated with loss of which gene?",["VHL","WT1","RB","NF2"],"Inactivation of VHL on chromosome 3p stabilises HIF and raises VEGF. Renal cell carcinoma can invade the renal vein."],["q-fcps-pat4-63","A thyroid nodule with calcitonin secretion and amyloid stroma occurring with pheochromocytoma suggests:",["MEN type 2A","MEN type 1","MEN type 2B","Von Hippel-Lindau"],"MEN 2A comprises medullary thyroid carcinoma, pheochromocytoma and parathyroid hyperplasia with a RET mutation."],["q-fcps-pat4-64","The classic triad of MEN type 1 consists of tumours of the parathyroid, pituitary and:",["Pancreas","Adrenal medulla","Thyroid C cells","Ovary"],"MEN 1 (Wermer syndrome) involves a menin mutation and presents with parathyroid hyperplasia, pituitary adenomas and pancreatic tumours."],["q-fcps-pat4-65","Which type of thyroid cancer tends to spread by the bloodstream and is diagnosed by capsular or vascular invasion?",["Follicular carcinoma","Papillary carcinoma","Medullary carcinoma","Anaplastic carcinoma"],"Follicular carcinoma cannot be diagnosed on FNA cytology alone, and it spreads to the lungs and bone."],["q-fcps-pat4-66","Which finding on cervical cytology indicates infection with HPV?",["Koilocytes","Clue cells","Psammoma bodies","Reed-Sternberg cells"],"Koilocytes have perinuclear halos and raisinoid nuclei."],["q-fcps-pat4-67","Codman triangle on X-ray is typical of:",["Osteosarcoma","Osteochondroma","Giant cell tumour","Osteoid osteoma"],"Periosteal elevation by an aggressive tumour produces a Codman triangle and a sunburst pattern, commonly around the knee in adolescents."],["q-fcps-pat4-68","A young boy has a lytic femoral lesion with 'onion skin' periosteal reaction and a t(11;22) translocation. The diagnosis is:",["Ewing sarcoma","Osteosarcoma","Chondrosarcoma","Osteoblastoma"],"Ewing sarcoma consists of small round blue cells with an EWS-FLI1 fusion."],["q-fcps-pat4-69","Rhomboid-shaped, weakly positively birefringent crystals in joint fluid indicate:",["Pseudogout (calcium pyrophosphate)","Gout","Septic arthritis","Haemarthrosis"],"Gout shows needle-shaped crystals with strong negative birefringence."],["q-fcps-pat4-70","Neurofibrillary tangles and amyloid plaques in the hippocampus are characteristic of:",["Alzheimer disease","Parkinson disease","Pick disease","Creutzfeldt-Jakob disease"],"Tau protein forms tangles and beta-amyloid forms plaques, with early loss of cholinergic neurons in the nucleus basalis."],["q-fcps-pat4-71","Pseudopalisading necrosis is a feature of:",["Glioblastoma","Meningioma","Medulloblastoma","Schwannoma"],"Glioblastoma is a grade 4 astrocytoma with necrosis and microvascular proliferation."],["q-fcps-pat4-72","Negri bodies are found in the neurons in:",["Rabies","Herpes encephalitis","Poliomyelitis","Tetanus"],"They are eosinophilic cytoplasmic inclusions seen in the hippocampus and Purkinje cells."],["q-fcps-pat4-73","Which skin tumour is characterised by pearly papules with rodent ulceration and palisading nuclei?",["Basal cell carcinoma","Squamous cell carcinoma","Melanoma","Keratoacanthoma"],"Basal cell carcinoma is locally invasive and rarely metastasises."],["q-fcps-pat4-74","Which prognostic factor is most important for cutaneous melanoma?",["Breslow thickness","Colour","Size of lesion","Site of lesion"],"Depth of invasion in millimetres (Breslow thickness) is the strongest predictor of metastasis."],["q-fcps-pat4-75","Pemphigus vulgaris differs from bullous pemphigoid in that it shows:",["Intraepidermal acantholysis with IgG against desmoglein","Subepidermal blisters","Antibodies against hemidesmosomes","Eosinophil-rich blisters only"],"Pemphigus has flaccid blisters, a positive Nikolsky sign and a net-like IgG pattern. Pemphigoid has tense subepidermal blisters."],["q-fcps-pat5-01","Which type of necrosis is typical of ischaemic infarcts in the brain?",["Liquefactive necrosis","Coagulative necrosis","Caseous necrosis","Fibrinoid necrosis"],"Most solid organs show coagulative necrosis in infarction, but the brain is rich in lipid and has little structural protein, so it liquefies."],["q-fcps-pat5-02","Which feature distinguishes apoptosis from necrosis?",["Cell shrinkage with no inflammation","Cell swelling","Release of lysosomal enzymes causing inflammation","Random DNA degradation"],"Apoptotic cells shrink, show chromatin condensation and form apoptotic bodies, and they are removed by phagocytes without an inflammatory response."],["q-fcps-pat5-03","The initiator caspase in the intrinsic (mitochondrial) pathway of apoptosis is:",["Caspase 9","Caspase 8","Caspase 3","Caspase 6"],"Cytochrome c release forms the apoptosome with Apaf-1, which activates caspase 9. Caspase 8 is the initiator in the extrinsic pathway."],["q-fcps-pat5-04","BCL2 acts to:",["Prevent apoptosis by blocking release of cytochrome c","Promote apoptosis","Activate p53","Cause DNA repair"],"BCL2 overexpression by t(14;18) in follicular lymphoma allows B cells to evade apoptosis."],["q-fcps-pat5-05","Which of the following is a reversible cell change?",["Cellular swelling","Karyolysis","Pyknosis","Karyorrhexis"],"Pyknosis, karyorrhexis and karyolysis are nuclear changes of irreversible injury."],["q-fcps-pat5-06","Replacement of one adult cell type by another that is better able to withstand stress is called:",["Metaplasia","Hyperplasia","Dysplasia","Hypertrophy"],"Barrett oesophagus is squamous-to-columnar metaplasia, and vitamin A deficiency causes columnar-to-squamous change."],["q-fcps-pat5-07","Lipofuscin is a:",["Wear-and-tear pigment from lipid peroxidation","Malarial pigment","Iron storage pigment","Pigment of Addison disease"],"It accumulates in ageing, in atrophic tissues such as the heart (brown atrophy) and liver."],["q-fcps-pat5-08","Which stain is used to demonstrate haemosiderin?",["Prussian blue","Congo red","Von Kossa","Oil red O"],"Congo red shows amyloid with apple-green birefringence under polarised light, and von Kossa stains calcium."],["q-fcps-pat5-09","Dystrophic calcification occurs:",["In dead or damaged tissue with normal serum calcium","With hypercalcaemia in normal tissue","Only in the kidneys","Only in neoplasms"],"Metastatic calcification is seen with hypercalcaemia, such as in hyperparathyroidism or vitamin D excess."],["q-fcps-pat5-10","The predominant cell in the first 6 to 24 hours of acute inflammation is:",["Neutrophil","Macrophage","Lymphocyte","Eosinophil"],"Monocytes and macrophages predominate after 24 to 48 hours."],["q-fcps-pat5-11","Which adhesion molecule on neutrophils binds ICAM-1 for firm adhesion?",["Integrins (LFA-1 and Mac-1)","Selectins","Cadherins","Sialyl Lewis X"],"Rolling is mediated by selectins and firm adhesion by integrins, and a defect of the beta-2 integrin chain causes leukocyte adhesion deficiency type 1."],["q-fcps-pat5-12","Leukocyte adhesion deficiency type 1 presents with:",["Delayed separation of the umbilical cord and recurrent infections without pus","Albinism and recurrent infections","Giant granules in leukocytes","Failure of the oxidative burst"],"Chediak-Higashi has giant lysosomal granules and albinism, and chronic granulomatous disease has an NADPH oxidase defect."],["q-fcps-pat5-13","Chronic granulomatous disease is diagnosed by:",["Nitroblue tetrazolium test or dihydrorhodamine flow cytometry","Flow cytometry for CD18","Bone marrow biopsy","Serum immunoglobulin levels"],"Patients are prone to infection with catalase-positive organisms such as Staphylococcus aureus, Aspergillus and Burkholderia."],["q-fcps-pat5-14","Which chemical mediator is the main cause of fever in inflammation?",["Prostaglandin E2 induced by IL-1 and TNF","Histamine","Bradykinin","Leukotriene C4"],"Pyrogenic cytokines raise the hypothalamic set point through PGE2, which is why aspirin lowers fever."],["q-fcps-pat5-15","Which mediator is the most important in the early phase of increased vascular permeability?",["Histamine","TNF","Interleukin-6","Interferon gamma"],"Histamine from mast cells acts on venules and gives the immediate transient response."],["q-fcps-pat5-16","The characteristic cell of granulomatous inflammation is:",["Epithelioid macrophage","Neutrophil","Eosinophil","Plasma cell"],"Interferon gamma from Th1 cells activates macrophages, which transform into epithelioid cells and giant cells."],["q-fcps-pat5-17","Non-caseating granulomas are characteristic of:",["Sarcoidosis","Tuberculosis","Histoplasmosis","Caseating pneumonia"],"Schaumann bodies and asteroid bodies may be seen in sarcoid giant cells, and serum ACE is raised."],["q-fcps-pat5-18","Which cell type is the major source of collagen in wound healing?",["Fibroblast","Macrophage","Endothelial cell","Neutrophil"],"Fibroblasts are stimulated by TGF-beta and PDGF to produce type III collagen first and then type I."],["q-fcps-pat5-19","Healing by secondary intention differs from primary intention in that it:",["Has more granulation tissue and wound contraction by myofibroblasts","Has less scarring","Has no inflammation","Heals in a shorter time"],"Large defects with tissue loss and infected wounds heal by secondary intention."],["q-fcps-pat5-20","Which collagen type predominates in granulation tissue and early scars?",["Type III","Type I","Type II","Type IV"],"Type IV forms basement membrane and type II is in cartilage."],["q-fcps-pat5-21","Wound strength reaches about what percentage of normal skin at 3 months?",["70 to 80%","100%","20%","40%"],"The wound never regains full strength of unwounded skin."],["q-fcps-pat5-22","Keloid differs from hypertrophic scar in that a keloid:",["Extends beyond the original wound margins and does not regress","Remains within the wound margin","Regresses spontaneously","Is composed of type II collagen"],"Keloids are more common in dark-skinned individuals and the collagen is thick and hyalinised."],["q-fcps-pat5-23","Virchow's triad includes all of the following EXCEPT:",["Hypercalcaemia","Endothelial injury","Stasis or turbulent flow","Hypercoagulability"],"These three factors predispose to thrombosis."],["q-fcps-pat5-24","Lines of Zahn are found in:",["Thrombi formed in flowing blood","Postmortem clots","Chicken-fat clots","Currant-jelly clots"],"They are alternating pale platelet-fibrin and dark red cell layers, and they indicate that the clot formed before death."],["q-fcps-pat5-25","The most common source of pulmonary emboli is:",["Deep veins of the lower limbs","Right atrium","Pelvic veins","Upper limb veins"],"Most arise from the femoral, iliac or popliteal veins."],["q-fcps-pat5-26","A paradoxical embolus passes from the venous to the arterial circulation through:",["A patent foramen ovale or other septal defect","The pulmonary artery","A bronchial artery","The ductus venosus"],"A venous thrombus can cause stroke or limb ischaemia in a patient with an atrial septal defect."],["q-fcps-pat5-27","Red infarcts occur in:",["Organs with a dual blood supply or loose tissue, such as lung and intestine","Heart","Kidney","Spleen"],"Heart, kidney and spleen have end-arterial supply and develop white (pale) infarcts."],["q-fcps-pat5-28","Which is the most common cause of disseminated intravascular coagulation in obstetrics?",["Placental abruption and amniotic fluid embolism","Hyperemesis","Pre-eclampsia only","Anaemia"],"Tissue factor release triggers widespread thrombosis and consumption of clotting factors."],["q-fcps-pat5-29","Laboratory findings in DIC include:",["Prolonged PT and aPTT, low platelets and raised D-dimer","Normal PT and aPTT, high platelets","Isolated prolonged bleeding time","Low D-dimer"],"Fibrinogen is low and schistocytes may be seen on the film."],["q-fcps-pat5-30","Hyperplasia of the prostate is under the influence of:",["Dihydrotestosterone","Oestrogen only","Progesterone","Prolactin"],"5-alpha reductase converts testosterone to DHT, and finasteride inhibits this enzyme."],["q-fcps-pat5-31","Which tumour suppressor gene is mutated most commonly in human cancers?",["TP53","RB1","APC","BRCA1"],"p53 induces cell cycle arrest or apoptosis in response to DNA damage."],["q-fcps-pat5-32","Retinoblastoma is associated with deletion on:",["Chromosome 13q14","Chromosome 17p","Chromosome 5q","Chromosome 11p"],"Knudson's two-hit hypothesis was derived from retinoblastoma, and the survivors have a high risk of osteosarcoma."],["q-fcps-pat5-33","Familial adenomatous polyposis is caused by mutation of:",["APC gene on chromosome 5q","DCC gene","KRAS","MLH1"],"The APC protein regulates beta-catenin, and untreated patients develop colorectal cancer in almost all cases."],["q-fcps-pat5-34","Lynch syndrome (HNPCC) is due to defects in:",["DNA mismatch repair genes","Nucleotide excision repair","Homologous recombination","Base excision repair"],"It is characterised by microsatellite instability and by cancers of the colon and endometrium."],["q-fcps-pat5-35","Xeroderma pigmentosum results from defective:",["Nucleotide excision repair","Mismatch repair","Homologous recombination","Non-homologous end joining"],"Thymine dimers caused by UV light are not removed, so skin cancers are common."],["q-fcps-pat5-36","The Philadelphia chromosome t(9;22) produces:",["BCR-ABL tyrosine kinase","PML-RARA","MYC overexpression","BCL2 overexpression"],"It is the hallmark of chronic myeloid leukaemia, and imatinib inhibits the fusion protein."],["q-fcps-pat5-37","t(8;14) is characteristic of:",["Burkitt lymphoma","Follicular lymphoma","Mantle cell lymphoma","Acute promyelocytic leukaemia"],"The MYC gene is translocated next to the immunoglobulin heavy chain gene, and the 'starry sky' appearance is typical."],["q-fcps-pat5-38","t(15;17) is seen in:",["Acute promyelocytic leukaemia","Chronic myeloid leukaemia","Burkitt lymphoma","Mantle cell lymphoma"],"All-trans retinoic acid induces differentiation, but DIC is a risk at presentation."],["q-fcps-pat5-39","Amplification of N-myc in a childhood tumour indicates:",["Neuroblastoma with poor prognosis","Wilms tumour","Medulloblastoma","Rhabdomyosarcoma"],"Neuroblastoma arises from neural crest cells in the adrenal medulla or sympathetic chain, and urinary VMA and HVA are raised."],["q-fcps-pat5-40","Her2/neu (ERBB2) amplification in breast cancer is treated with:",["Trastuzumab","Tamoxifen","Rituximab","Imatinib"],"Trastuzumab is a monoclonal antibody against HER2, and its main toxicity is cardiomyopathy."],["q-fcps-pat5-41","Which tumour marker is used for follow-up of hepatocellular carcinoma?",["Alpha-fetoprotein","CA 125","CA 19-9","CEA"],"CA 125 is used in ovarian cancer, CA 19-9 in pancreatic cancer and CEA in colorectal cancer."],["q-fcps-pat5-42","Psammoma bodies are seen in all of the following EXCEPT:",["Follicular carcinoma of the thyroid","Papillary carcinoma of the thyroid","Meningioma","Serous cystadenocarcinoma of the ovary"],"Follicular carcinoma is diagnosed by capsular and vascular invasion and spreads by the blood."],["q-fcps-pat5-43","Orphan Annie eye nuclei are characteristic of:",["Papillary carcinoma of the thyroid","Medullary carcinoma","Anaplastic carcinoma","Follicular adenoma"],"They are optically clear nuclei with grooves and pseudoinclusions, and papillary carcinoma spreads to lymph nodes."],["q-fcps-pat5-44","Medullary carcinoma of the thyroid arises from:",["Parafollicular C cells and secretes calcitonin","Follicular cells","Chief cells","Oxyphil cells"],"Amyloid stroma is typical, and the tumour is part of MEN 2 with RET mutation."],["q-fcps-pat5-45","Reed-Sternberg cells are seen in:",["Hodgkin lymphoma","Burkitt lymphoma","Multiple myeloma","Hairy cell leukaemia"],"Classical RS cells are CD15 and CD30 positive and CD45 negative."],["q-fcps-pat5-46","The most common subtype of classical Hodgkin lymphoma is:",["Nodular sclerosis","Mixed cellularity","Lymphocyte-rich","Lymphocyte-depleted"],"Lacunar cells and collagen bands dividing the node are typical, and it is most common in young women."],["q-fcps-pat5-47","Rouleaux formation and Bence Jones proteins are features of:",["Multiple myeloma","Waldenstrom macroglobulinaemia","Hodgkin lymphoma","CLL"],"The 'punched-out' lytic bone lesions, hypercalcaemia, renal failure and anaemia are the usual presenting problems."],["q-fcps-pat5-48","Smudge cells in the peripheral blood are characteristic of:",["Chronic lymphocytic leukaemia","Acute lymphoblastic leukaemia","Hairy cell leukaemia","CML"],"CLL is the commonest leukaemia in the elderly in the West and the cells are CD5 and CD23 positive."],["q-fcps-pat5-49","Auer rods are found in:",["Acute myeloid leukaemia","Acute lymphoblastic leukaemia","CLL","Multiple myeloma"],"They are needle-like azurophilic inclusions of fused primary granules, and they are myeloperoxidase positive."],["q-fcps-pat5-50","Tartrate-resistant acid phosphatase positivity is characteristic of:",["Hairy cell leukaemia","CLL","Myeloma","ALL"],"Cladribine is the treatment of choice, and BRAF V600E is the usual mutation."],["q-fcps-pat5-51","Which finding is typical of iron deficiency anaemia?",["Low serum ferritin and high TIBC","High ferritin and low TIBC","High serum iron","Normal TIBC with low ferritin"],"Anaemia of chronic disease has low iron and low TIBC but high or normal ferritin."],["q-fcps-pat5-52","Ringed sideroblasts are seen in:",["Sideroblastic anaemia","Iron deficiency","Thalassaemia minor","Megaloblastic anaemia"],"Defective haem synthesis leads to iron accumulation in mitochondria around the nucleus."],["q-fcps-pat5-53","A patient with macrocytic anaemia and subacute combined degeneration of the cord has deficiency of:",["Vitamin B12","Folate","Iron","Vitamin C"],"Folate deficiency causes megaloblastic anaemia without neurological findings."],["q-fcps-pat5-54","In beta thalassaemia major the dominant haemoglobin in the red cells is:",["HbF","HbA","HbA2 only","HbS"],"Beta chain production is absent, so excess alpha chains precipitate and cause ineffective erythropoiesis."],["q-fcps-pat5-55","Hb Bart's hydrops fetalis results from deletion of:",["All four alpha globin genes","One alpha gene","Two alpha genes","Both beta genes"],"Gamma chain tetramers have very high oxygen affinity, and so tissue oxygen delivery is poor."],["q-fcps-pat5-56","The mutation in sickle cell disease is:",["Glutamic acid to valine at position 6 of the beta chain","Valine to glutamic acid","Glutamic acid to lysine at position 6","Deletion of phenylalanine"],"HbC has lysine instead of glutamate at position 6."],["q-fcps-pat5-57","Howell-Jolly bodies are seen after:",["Splenectomy","Hepatectomy","Thymectomy","Adrenalectomy"],"They are nuclear remnants in red cells that the spleen would normally remove."],["q-fcps-pat5-58","The most common inherited bleeding disorder is:",["Von Willebrand disease","Haemophilia A","Haemophilia B","Factor XI deficiency"],"It gives a prolonged bleeding time, a normal or prolonged aPTT and an abnormal ristocetin response."],["q-fcps-pat5-59","Immune thrombocytopenic purpura in children typically:",["Follows a viral infection and is self-limiting","Is chronic in most cases","Has splenomegaly","Needs splenectomy in most"],"Antibodies against platelet glycoprotein IIb/IIIa cause splenic destruction."],["q-fcps-pat5-60","Thrombotic thrombocytopenic purpura results from deficiency of:",["ADAMTS13","Factor VIII","Protein C","Antithrombin"],"Ultra-large von Willebrand multimers cause platelet microthrombi, and the pentad is fever, anaemia, thrombocytopenia, renal failure and neurological signs."],["q-fcps-pat5-61","Heparin-induced thrombocytopenia is due to antibodies against:",["Platelet factor 4-heparin complex","Factor Xa","Antithrombin","Fibrinogen"],"It paradoxically causes thrombosis and heparin must be stopped, with an alternative such as argatroban."],["q-fcps-pat5-62","Reversible cell injury causes all of these EXCEPT:",["Membrane rupture","Mitochondrial swelling","Decreased ATP","Cell blebs"],"Severe membrane damage and calcium influx mark the point of no return."],["q-fcps-pat5-63","Which type of hypersensitivity is responsible for Goodpasture syndrome?",["Type II","Type I","Type III","Type IV"],"Antibodies against type IV collagen of the alpha-3 chain cause linear IgG deposition in glomeruli and alveoli."],["q-fcps-pat5-64","Serum sickness is an example of:",["Type III hypersensitivity","Type I hypersensitivity","Type II hypersensitivity","Type IV hypersensitivity"],"Immune complexes deposit in vessels and joints and activate complement, with low C3."],["q-fcps-pat5-65","Contact dermatitis from nickel is:",["Type IV hypersensitivity","Type I hypersensitivity","Type II hypersensitivity","Type III hypersensitivity"],"It is mediated by T cells and develops over 48 to 72 hours."],["q-fcps-pat5-66","Which complement deficiency predisposes to recurrent Neisseria infections?",["Terminal components C5 to C9","C1 inhibitor","C3 only","Decay-accelerating factor"],"Eculizumab, a C5 inhibitor, also increases the risk of meningococcal disease."],["q-fcps-pat5-67","Amyloid derived from immunoglobulin light chains is termed:",["AL amyloid","AA amyloid","ATTR amyloid","Abeta2m amyloid"],"AA amyloid is from serum amyloid A in chronic inflammation, such as rheumatoid arthritis and familial Mediterranean fever."],["q-fcps-pat5-68","Dialysis-associated amyloidosis is composed of:",["Beta-2 microglobulin","Transthyretin","Serum amyloid A","Light chains"],"It typically causes carpal tunnel syndrome and arthropathy."],["q-fcps-pat5-69","Which is the best site for biopsy to diagnose systemic amyloidosis with minimal risk?",["Abdominal fat pad aspirate or rectal biopsy","Liver","Kidney","Heart"],"Congo red positive material shows apple-green birefringence."],["q-fcps-pat5-70","The Mallory-Denk body in the liver is composed of:",["Damaged intermediate keratin filaments","Alpha-1 antitrypsin","Copper","Iron"],"It is typical of alcoholic hepatitis, but also seen in primary biliary cholangitis and Wilson disease."],["q-fcps-pat5-71","Alpha-1 antitrypsin deficiency shows in the liver:",["PAS-positive, diastase-resistant globules","Orcein-positive granules","Rhodanine granules","Prussian blue granules"],"It causes panacinar emphysema in the lung and cirrhosis in the liver."],["q-fcps-pat5-72","Primary biliary cholangitis is characterised by:",["Anti-mitochondrial antibodies and raised alkaline phosphatase","p-ANCA and beading of bile ducts","Anti-smooth muscle antibodies","Anti-LKM antibodies"],"It is most common in middle-aged women and causes pruritus and fatigue."],["q-fcps-pat5-73","Primary sclerosing cholangitis is associated with:",["Ulcerative colitis and p-ANCA","Crohn disease and ASCA","Coeliac disease","Peptic ulcer"],"It has a 'beaded' appearance of bile ducts on cholangiography and increases the risk of cholangiocarcinoma."],["q-fcps-pat5-74","Which feature suggests Crohn disease rather than ulcerative colitis?",["Skip lesions with transmural inflammation and granulomas","Continuous mucosal disease from the rectum","Crypt abscesses limited to the mucosa","Toxic megacolon only"],"Crohn disease may affect any part of the gut, with fistulae and strictures."],["q-fcps-pat5-75","Intestinal metaplasia of the gastric mucosa is associated with:",["Chronic Helicobacter pylori gastritis and gastric adenocarcinoma","Duodenal ulcer","Zollinger-Ellison syndrome","Menetrier disease"],"Duodenal ulcers are associated with antral-predominant gastritis and high acid output."],["q-fcps-pat5-76","Krukenberg tumour is a metastasis to the ovary, usually from:",["Gastric signet-ring cell carcinoma","Breast","Lung","Pancreas"],"The tumour is bilateral and made of mucin-secreting signet-ring cells."],["q-fcps-pat5-77","Which histological pattern is seen in the lung in acute respiratory distress syndrome?",["Diffuse alveolar damage with hyaline membranes","Granulomas","Honeycomb change only","Bronchiolitis obliterans"],"Hyaline membranes are composed of fibrin and necrotic epithelial debris."],["q-fcps-pat5-78","Ghon complex consists of:",["A subpleural parenchymal focus and hilar lymph node involvement","A cavity at the apex","Miliary nodules","Pleural effusion alone"],"A calcified Ghon complex is called a Ranke complex."],["q-fcps-pat5-79","Asbestos exposure is most associated with:",["Mesothelioma and bronchogenic carcinoma","Small cell carcinoma only","Berylliosis","Byssinosis"],"Ferruginous bodies are asbestos fibres coated with iron-protein complex, and pleural plaques are common."],["q-fcps-pat5-80","Small cell lung carcinoma is associated with all of the following EXCEPT:",["Squamous differentiation with keratin pearls","Central location","ACTH secretion","SIADH"],"Keratin pearls are a feature of squamous cell carcinoma, which is also associated with hypercalcaemia from PTHrP."],["q-fcps-pat5-81","The most common type of lung cancer in non-smokers is:",["Adenocarcinoma","Squamous cell carcinoma","Small cell carcinoma","Large cell carcinoma"],"EGFR mutations are more frequent in non-smoking women, and ALK rearrangement in younger patients."],["q-fcps-pat5-82","Which glomerular disease is the commonest cause of nephrotic syndrome in children?",["Minimal change disease","Membranous nephropathy","FSGS","IgA nephropathy"],"Electron microscopy shows effacement of podocyte foot processes and the disease responds to steroids."],["q-fcps-pat5-83","'Spike and dome' appearance on silver stain is seen in:",["Membranous nephropathy","Minimal change disease","Post-streptococcal glomerulonephritis","Alport syndrome"],"Subepithelial immune deposits with basement membrane projections give the spikes. Anti-PLA2R antibodies are found in most primary cases."],["q-fcps-pat5-84","'Humps' (subepithelial deposits) on electron microscopy occur in:",["Post-streptococcal glomerulonephritis","Membranous nephropathy","Alport syndrome","Minimal change disease"],"Immunofluorescence shows a granular 'starry sky' pattern and C3 is low."],["q-fcps-pat5-85","Crescents in the glomeruli are a feature of:",["Rapidly progressive glomerulonephritis","Minimal change disease","Diabetic nephropathy","Amyloidosis"],"Crescents are formed by proliferation of parietal epithelial cells and macrophages."],["q-fcps-pat5-86","Kimmelstiel-Wilson lesions are:",["Nodular glomerulosclerosis in diabetes","Wire loop lesions in SLE","Crescents in Goodpasture syndrome","Mesangial IgA deposits"],"They are PAS-positive mesangial nodules."],["q-fcps-pat5-87","Wire loop lesions are characteristic of:",["Lupus nephritis class IV","Diabetic nephropathy","Minimal change disease","Alport syndrome"],"Diffuse proliferative lupus nephritis is the most severe and the most common form."],["q-fcps-pat5-88","Renal cell carcinoma is associated with deletion or inactivation of:",["VHL gene on chromosome 3p","WT1","p53 on 17p","RB1"],"Clear cell carcinoma is the commonest type, and the tumour may secrete erythropoietin."],["q-fcps-pat5-89","Wilms tumour is associated with:",["WT1 mutation and aniridia in WAGR syndrome","RET mutation","BRCA1","NF2"],"It is the commonest renal tumour in children and shows blastemal, stromal and epithelial components."],["q-fcps-pat5-90","Seminoma is characterised histologically by:",["Large cells with clear cytoplasm and a lymphocytic infiltrate","Schiller-Duval bodies","Syncytiotrophoblasts only","Reinke crystals"],"Seminoma is highly radiosensitive and may have raised placental alkaline phosphatase."],["q-fcps-pat5-91","Schiller-Duval bodies are characteristic of:",["Yolk sac tumour","Seminoma","Choriocarcinoma","Teratoma"],"The tumour secretes alpha-fetoprotein, while choriocarcinoma secretes beta-hCG."],["q-fcps-pat5-92","Which ovarian tumour is associated with Meigs syndrome?",["Fibroma","Dysgerminoma","Brenner tumour","Granulosa cell tumour"],"Meigs syndrome is ovarian fibroma, ascites and right pleural effusion."],["q-fcps-pat5-93","Call-Exner bodies are seen in:",["Granulosa cell tumour","Sertoli-Leydig cell tumour","Dysgerminoma","Mucinous cystadenoma"],"The tumour secretes oestrogen and may cause precocious puberty or endometrial hyperplasia."],["q-fcps-pat5-94","Which gene is most associated with hereditary breast and ovarian cancer syndrome?",["BRCA1","TP53","PTEN","CDH1"],"BRCA1 is on 17q21 and BRCA2 is on 13q12."],["q-fcps-pat5-95","Hydatidiform mole: a complete mole is typically:",["46,XX of paternal origin only","69,XXY","Containing fetal parts","Associated with a low hCG"],"A partial mole is usually triploid and may have fetal tissue."],["q-fcps-pat5-96","Which finding is most typical of fibroadenoma of the breast?",["A well-circumscribed mobile mass in a young woman","Hard fixed mass with skin dimpling","Bloody nipple discharge in an elderly woman","Bilateral painful nodularity"],"It is the most common benign breast tumour and has a stromal and ductal component."],["q-fcps-pat5-97","Which histological type of invasive breast carcinoma is the commonest?",["Invasive ductal carcinoma (no special type)","Invasive lobular carcinoma","Medullary carcinoma","Mucinous carcinoma"],"Invasive lobular carcinoma is characterised by loss of E-cadherin and a single-file pattern."],["q-fcps-pat6-01","The commonest cause of acute bacterial endocarditis is:",["Staphylococcus aureus","Streptococcus viridans","Enterococcus","Candida"],"Viridans streptococci cause subacute endocarditis on damaged valves."],["q-fcps-pat6-02","Libman-Sacks endocarditis is associated with:",["Systemic lupus erythematosus","Rheumatic fever","Malignancy","Intravenous drug use"],"Verrucae are on both surfaces of the valve, and non-bacterial thrombotic endocarditis is associated with cancer."],["q-fcps-pat6-03","Aschoff bodies are seen in:",["Rheumatic heart disease","Infective endocarditis","Myocarditis due to viral infection","Sarcoidosis"],"Anitschkow cells with caterpillar chromatin are the characteristic cells."],["q-fcps-pat6-04","The valve most commonly affected in rheumatic heart disease is the:",["Mitral valve","Aortic valve","Tricuspid valve","Pulmonary valve"],"It leads to mitral stenosis with a 'fish-mouth' orifice."],["q-fcps-pat6-05","Calcific aortic stenosis in a 70-year-old is due to:",["Age-related degenerative calcification","Rheumatic fever","Infective endocarditis","Marfan syndrome"],"A bicuspid valve causes it earlier, at about 50 to 60 years."],["q-fcps-pat6-06","Cystic medial necrosis is seen in:",["Marfan syndrome and aortic dissection","Atherosclerosis only","Takayasu arteritis","Syphilitic aortitis"],"Hypertension is the commonest risk factor for dissection."],["q-fcps-pat6-07","Tree-barking of the aorta is seen in:",["Tertiary syphilis","Atherosclerosis","Takayasu arteritis","Marfan syndrome"],"Endarteritis of the vasa vasorum causes ischaemia of the media."],["q-fcps-pat6-08","Giant cell (temporal) arteritis can lead to:",["Blindness through ophthalmic artery involvement","Aortic dissection only","Renal failure","Pulmonary haemorrhage"],"It occurs in patients over 50, with raised ESR and responds to steroids."],["q-fcps-pat6-09","Takayasu arteritis typically affects:",["Young Asian women with absent pulses","Elderly men","Children","Pregnant women only"],"It is also called pulseless disease and affects the aortic arch."],["q-fcps-pat6-10","Kawasaki disease complicates mainly with:",["Coronary artery aneurysm","Renal failure","Pulmonary fibrosis","Aortic stenosis"],"Treatment is intravenous immunoglobulin and aspirin."],["q-fcps-pat6-11","Polyarteritis nodosa is associated with:",["Hepatitis B and spares the lungs","Hepatitis C","p-ANCA and lung involvement","c-ANCA"],"It causes microaneurysms and involves medium arteries."],["q-fcps-pat6-12","Buerger disease (thromboangiitis obliterans) is strongly associated with:",["Smoking","Hypertension","Diabetes","Hyperlipidaemia"],"It affects the small and medium vessels of the extremities in young male smokers."],["q-fcps-pat6-13","Hyaline arteriolosclerosis is characteristic of:",["Benign hypertension and diabetes","Malignant hypertension","Vasculitis","Atherosclerosis"],"Hyperplastic (onion-skin) arteriolosclerosis is characteristic of malignant hypertension."],["q-fcps-pat6-14","The commonest site of atherosclerosis is the:",["Abdominal aorta","Thoracic aorta","Carotid artery only","Radial artery"],"The order is abdominal aorta, coronary arteries, popliteal artery, descending thoracic aorta, then carotid arteries."],["q-fcps-pat6-15","Which coronary artery is most commonly occluded in myocardial infarction?",["Left anterior descending artery","Right coronary artery","Left circumflex artery","Posterior descending artery"],"It supplies the anterior wall and the apex and the anterior two-thirds of the interventricular septum."],["q-fcps-pat6-16","The earliest light-microscopic change in myocardial infarction (4 to 12 hours) is:",["Coagulative necrosis with wavy fibres","Neutrophil infiltration","Granulation tissue","Fibrous scar"],"Neutrophils appear at 1 to 3 days, macrophages at 3 to 7 days, and granulation tissue at 1 to 2 weeks."],["q-fcps-pat6-17","Cardiac rupture after myocardial infarction is most likely at:",["3 to 7 days","First 24 hours","After 2 months","After 1 year"],"This is the time of maximal softening because of macrophage activity."],["q-fcps-pat6-18","Dressler syndrome occurs:",["Weeks after myocardial infarction, as autoimmune pericarditis","In the first hours","In the first day","Only after surgery"],"It is a fibrinous pericarditis mediated by antibodies against myocardium."],["q-fcps-pat6-19","Which cardiomyopathy shows asymmetric septal hypertrophy and myocyte disarray?",["Hypertrophic cardiomyopathy","Dilated cardiomyopathy","Restrictive cardiomyopathy","Takotsubo cardiomyopathy"],"It is caused by sarcomere gene mutations and is a leading cause of sudden death in young athletes."],["q-fcps-pat6-20","Alcohol and doxorubicin cause which type of cardiomyopathy?",["Dilated","Hypertrophic","Restrictive","Arrhythmogenic"],"Peripartum and viral causes are others."],["q-fcps-pat6-21","The most common primary cardiac tumour in adults is:",["Myxoma","Rhabdomyoma","Lipoma","Angiosarcoma"],"It is in the left atrium and causes a 'tumour plop'; rhabdomyoma is the commonest in children and associated with tuberous sclerosis."],["q-fcps-pat6-22","Which is the most common cause of community-acquired pneumonia?",["Streptococcus pneumoniae","Klebsiella","Staphylococcus aureus","Mycoplasma"],"Lobar consolidation passes through congestion, red hepatisation, grey hepatisation and resolution."],["q-fcps-pat6-23","The stage of lobar pneumonia with fibrinopurulent exudate and a grey appearance is:",["Grey hepatisation","Red hepatisation","Congestion","Resolution"],"Red hepatisation has red cells and neutrophils in the alveoli."],["q-fcps-pat6-24","Klebsiella pneumonia is classically seen in:",["Alcoholics and diabetics, with currant jelly sputum","Neonates","HIV only","Healthy children"],"Abscess formation is common."],["q-fcps-pat6-25","Bronchiectasis is associated with all of these EXCEPT:",["Alpha-1 antitrypsin deficiency","Cystic fibrosis","Kartagener syndrome","Tuberculosis"],"Alpha-1 antitrypsin deficiency causes emphysema."],["q-fcps-pat6-26","Centriacinar emphysema is associated with:",["Smoking","Alpha-1 antitrypsin deficiency","Ageing","Interstitial fibrosis"],"It is most prominent in the upper lobes, while panacinar emphysema affects the lower lobes."],["q-fcps-pat6-27","Reid index is increased in:",["Chronic bronchitis","Emphysema","Asthma","Bronchiectasis"],"It is the ratio of mucous gland thickness to the bronchial wall thickness."],["q-fcps-pat6-28","The usual histological pattern of idiopathic pulmonary fibrosis is:",["Usual interstitial pneumonia with honeycombing","Granulomas","Diffuse alveolar damage","Bronchiolitis obliterans"],"It affects the lower lobes and subpleural areas."],["q-fcps-pat6-29","Silicosis predisposes to:",["Tuberculosis","Mesothelioma","Asthma only","Pneumothorax only"],"Eggshell calcification of hilar nodes is characteristic."],["q-fcps-pat6-30","Coal worker's pneumoconiosis shows:",["Carbon-laden macrophages and coal macules","Ferruginous bodies","Caseating granulomas","Hyaline membranes"],"Anthracosis is harmless pigment deposition."],["q-fcps-pat6-31","Berylliosis resembles:",["Sarcoidosis","Asbestosis","Silicosis","Pneumonia"],"It causes non-caseating granulomas."],["q-fcps-pat6-32","A Pancoast tumour causes:",["Horner syndrome and arm pain","SVC syndrome only","Pleural effusion only","Haemoptysis only"],"It is a tumour at the lung apex that invades the sympathetic chain and the brachial plexus."],["q-fcps-pat6-33","Which tumour is most associated with SIADH?",["Small cell carcinoma of the lung","Squamous cell carcinoma","Adenocarcinoma","Large cell carcinoma"],"Squamous carcinoma is associated with PTHrP secretion."],["q-fcps-pat6-34","Hepatitis B surface antigen with anti-HBc IgM suggests:",["Acute hepatitis B","Chronic hepatitis B","Immunisation","Past infection"],"Vaccinated persons have anti-HBs only."],["q-fcps-pat6-35","Ground-glass hepatocytes are seen in:",["Chronic hepatitis B","Hepatitis A","Hepatitis C","Alcoholic hepatitis"],"HBsAg accumulates in the endoplasmic reticulum."],["q-fcps-pat6-36","Hepatitis C is characterised by:",["A high rate of chronicity and lymphoid aggregates in portal tracts","Faecal-oral spread","Vaccine protection","Rare chronicity"],"It is the commonest cause of liver transplantation, with a risk of hepatocellular carcinoma."],["q-fcps-pat6-37","Councilman bodies are:",["Apoptotic hepatocytes","Mallory bodies","Ground-glass cells","Kupffer cells"],"They are seen in viral hepatitis and yellow fever."],["q-fcps-pat6-38","Bridging necrosis is seen in:",["Severe acute or chronic hepatitis","Hepatitis A mild","Fatty liver","Normal ageing"],"It links portal tracts to central veins."],["q-fcps-pat6-39","Micronodular cirrhosis is most characteristic of:",["Alcoholic liver disease","Viral hepatitis","Wilson disease","Primary biliary cholangitis only"],"Viral and post-necrotic cirrhosis are macronodular."],["q-fcps-pat6-40","The commonest cause of hepatocellular carcinoma worldwide is:",["Chronic hepatitis B","Alcohol","Aflatoxin alone","Haemochromatosis"],"Aflatoxin B1 causes a TP53 codon 249 mutation."],["q-fcps-pat6-41","The most common primary liver tumour in children is:",["Hepatoblastoma","Hepatocellular carcinoma","Haemangioma","Cholangiocarcinoma"],"Alpha-fetoprotein is raised."],["q-fcps-pat6-42","Which tumour is associated with oral contraceptive use?",["Hepatic adenoma","Hepatoblastoma","Cholangiocarcinoma","Angiosarcoma"],"Vinyl chloride is associated with angiosarcoma."],["q-fcps-pat6-43","Courvoisier's law states that a palpable gallbladder with painless jaundice suggests:",["Carcinoma of the head of the pancreas","Gallstones","Hepatitis","Cholangitis"],"Gallstone disease causes a fibrosed contracted gallbladder."],["q-fcps-pat6-44","The most common type of gallstone in the West is:",["Cholesterol stone","Pigment stone","Calcium carbonate stone","Mixed pigment stone"],"Risk factors are female sex, fertility, fat and forty."],["q-fcps-pat6-45","Pigment gallstones are associated with:",["Chronic haemolysis","Obesity","Oral contraceptives","Pregnancy"],"Sickle cell disease and hereditary spherocytosis are examples."],["q-fcps-pat6-46","Chronic pancreatitis in adults is most commonly due to:",["Alcohol","Gallstones","Hypercalcaemia","Trauma"],"Gallstones are the commonest cause of acute pancreatitis along with alcohol."],["q-fcps-pat6-47","Carcinoma of the pancreas is associated with:",["KRAS mutation and migratory thrombophlebitis","BRAF mutation","RET mutation","EGFR mutation"],"Trousseau sign refers to migratory thrombophlebitis."],["q-fcps-pat6-48","Which of the following is premalignant in the oesophagus?",["Barrett oesophagus","Achalasia of short duration","Mallory-Weiss tear","Hiatus hernia"],"It predisposes to adenocarcinoma."],["q-fcps-pat6-49","Squamous cell carcinoma of the oesophagus is associated with:",["Smoking, alcohol, hot beverages and achalasia","GERD","Barrett oesophagus","H. pylori"],"It is more common in the middle third."],["q-fcps-pat6-50","The commonest site of gastric ulcer is the:",["Lesser curvature near the incisura","Greater curvature","Fundus","Pyloric canal"],"Duodenal ulcers are in the first part of the duodenum."],["q-fcps-pat6-51","A gastric ulcer with heaped-up margins suggests:",["Malignancy","Benign ulcer with clean margins","Zollinger-Ellison syndrome","Peptic ulcer healing"],"Benign ulcers have punched-out margins and radiating mucosal folds."],["q-fcps-pat6-52","Linitis plastica is a feature of:",["Diffuse gastric carcinoma","Intestinal-type gastric carcinoma","Gastric lymphoma","Gastric ulcer"],"It is characterised by signet-ring cells and loss of E-cadherin."],["q-fcps-pat6-53","Gastric MALT lymphoma is associated with:",["Helicobacter pylori","EBV","HIV","HCV"],"Early disease regresses with eradication of the organism."],["q-fcps-pat6-54","Coeliac disease is associated with:",["HLA-DQ2 and HLA-DQ8 and villous atrophy","HLA-B27","HLA-DR3","HLA-DR4"],"Anti-tissue transglutaminase and anti-endomysial antibodies are diagnostic aids, with dermatitis herpetiformis in some."],["q-fcps-pat6-55","Whipple disease is caused by:",["Tropheryma whipplei, with PAS-positive macrophages","Giardia","Mycobacterium avium","Cryptosporidium"],"It presents with diarrhoea, arthralgia and weight loss."],["q-fcps-pat6-56","Hirschsprung disease results from:",["Absence of ganglion cells in the myenteric plexus","Hypertrophy of the muscle","Absent mucosa","Excess ganglion cells"],"It is associated with a RET mutation and the aganglionic segment is contracted."],["q-fcps-pat6-57","In ulcerative colitis, the risk of colon cancer is related to:",["Extent and duration of disease","Age at onset alone","Smoking","Diet"],"Smoking is protective in UC and a risk factor in Crohn disease."],["q-fcps-pat6-58","The adenoma-carcinoma sequence order of genetic events is:",["APC, KRAS, then TP53","TP53, KRAS, then APC","KRAS, TP53, then APC","APC, TP53, then KRAS"],"Villous adenomas have a higher malignant potential than tubular adenomas."],["q-fcps-pat6-59","Peutz-Jeghers syndrome is characterised by:",["Hamartomatous polyps and mucocutaneous pigmentation (STK11)","Adenomatous polyps","Juvenile polyps only","Hyperplastic polyps"],"There is increased risk of cancer of the breast, pancreas and GI tract."],["q-fcps-pat6-60","Carcinoid syndrome occurs when a tumour:",["Has metastasised to the liver so serotonin escapes first-pass metabolism","Is in the appendix only","Is in the rectum","Secretes insulin"],"Urinary 5-HIAA is raised; features include flushing, diarrhoea and right-sided heart valve fibrosis."],["q-fcps-pat6-61","The commonest site of carcinoid tumour is:",["Small intestine and appendix","Stomach","Lung","Pancreas"],"Appendiceal carcinoids rarely metastasise."],["q-fcps-pat6-62","The most common cause of acute appendicitis is:",["Faecolith obstruction","Tumour","Parasite","Foreign body"],"Luminal obstruction causes raised pressure and ischaemia."],["q-fcps-pat6-63","Pseudomyxoma peritonei results from rupture of a:",["Mucinous tumour of the appendix or ovary","Serous cystadenoma","Carcinoid","Colon carcinoma"],"Gelatinous mucin fills the abdomen."],["q-fcps-pat6-64","Which type of renal stone is the commonest?",["Calcium oxalate","Struvite","Uric acid","Cystine"],"Struvite stones are associated with urease-producing organisms such as Proteus and form staghorn calculi."],["q-fcps-pat6-65","Uric acid stones are:",["Radiolucent","Radio-opaque","Associated with alkaline urine","Associated with Proteus"],"They dissolve with urinary alkalinisation."],["q-fcps-pat6-66","Acute tubular necrosis most commonly follows:",["Ischaemia or nephrotoxins","Glomerulonephritis","Obstruction","Chronic infection"],"Muddy brown granular casts are seen in urine."],["q-fcps-pat6-67","Chronic pyelonephritis is usually associated with:",["Vesicoureteric reflux","Hypertension alone","Diabetes only","Nephrotic syndrome"],"It gives coarse scars with blunted calyces, and thyroidisation of tubules."],["q-fcps-pat6-68","Autosomal dominant polycystic kidney disease is associated with:",["Berry aneurysms and PKD1 mutation","PKHD1","Wilms tumour","Medullary sponge kidney"],"Liver cysts and mitral valve prolapse also occur."],["q-fcps-pat6-69","Urothelial carcinoma of the bladder is associated with:",["Smoking, aniline dyes and cyclophosphamide","Schistosoma haematobium","Chronic cystitis","Stones"],"Squamous carcinoma is associated with schistosomiasis."],["q-fcps-pat6-70","Prostate cancer most commonly arises in the:",["Peripheral zone","Transition zone","Central zone","Periurethral zone"],"BPH arises in the transition zone, and PSA is a screening marker."],["q-fcps-pat6-71","The Gleason score is used for grading of:",["Prostate adenocarcinoma","Breast carcinoma","Bladder carcinoma","Renal carcinoma"],"It is the sum of the two most prevalent patterns."],["q-fcps-pat6-72","Cervical intraepithelial neoplasia is caused mainly by:",["HPV types 16 and 18","HPV 6 and 11","HSV-2","Chlamydia"],"HPV 6 and 11 cause genital warts."],["q-fcps-pat6-73","The most common type of endometrial carcinoma is:",["Endometrioid adenocarcinoma, related to unopposed oestrogen","Serous carcinoma","Clear cell carcinoma","Carcinosarcoma"],"Obesity, nulliparity and tamoxifen are risk factors."],["q-fcps-pat6-74","Endometriosis is characterised by:",["Endometrial glands and stroma outside the uterus","Endometrial polyps","Glands within the myometrium","Hyperplasia of the endometrium"],"Glands within the myometrium are adenomyosis, and 'chocolate cysts' occur in the ovary."],["q-fcps-pat6-75","The commonest benign tumour in women is:",["Leiomyoma (fibroid)","Fibroadenoma","Dermoid cyst","Endometrial polyp"],"Malignant change to leiomyosarcoma is rare."],["q-fcps-pat6-76","Pre-eclampsia is characterised by:",["Hypertension and proteinuria after 20 weeks","Hypertension before 20 weeks","Seizures only","Oedema only"],"HELLP syndrome has haemolysis, elevated liver enzymes and low platelets."],["q-fcps-pat6-77","Choriocarcinoma most commonly follows:",["Complete hydatidiform mole","Normal pregnancy","Ectopic pregnancy","Partial mole"],"It is highly chemosensitive and spreads by the blood to the lung."],["q-fcps-pat6-78","Phyllodes tumour of the breast has:",["Leaf-like architecture with a cellular stroma","Only epithelial cells","Signet-ring cells","Comedo necrosis"],"It is usually benign but can recur."],["q-fcps-pat6-79","Paget disease of the nipple is associated with:",["An underlying ductal carcinoma","Lobular carcinoma","Benign papilloma","Fibrocystic change"],"Large cells with clear halo (Paget cells) infiltrate the epidermis."],["q-fcps-pat6-80","Comedo necrosis is typical of:",["High-grade ductal carcinoma in situ","Lobular carcinoma in situ","Fibroadenoma","Papilloma"],"It often shows calcification on mammography."],["q-fcps-pat6-81","Fibrocystic change without epithelial hyperplasia carries:",["No increased risk of breast cancer","A high risk","A moderate risk","A very high risk"],"Atypical hyperplasia raises the risk about 4 to 5 times."],["q-fcps-pat6-82","Gynaecomastia may be caused by all of these EXCEPT:",["Androgen excess","Cirrhosis","Digoxin","Spironolactone"],"Excess oestrogen relative to androgen is the mechanism."],["q-fcps-pat6-83","Which pituitary adenoma is the most common?",["Prolactinoma","Growth hormone adenoma","ACTH adenoma","Non-functioning"],"Dopamine agonists are the first-line treatment."],["q-fcps-pat6-84","Sheehan syndrome is:",["Postpartum pituitary necrosis","Pituitary adenoma","Empty sella","Craniopharyngioma"],"The first sign is failure of lactation."],["q-fcps-pat6-85","Hashimoto thyroiditis shows:",["Lymphoid follicles with germinal centres and Hurthle cells","Granulomas with giant cells","Fibrosis extending beyond the capsule","Colloid-rich follicles"],"Anti-thyroid peroxidase and anti-thyroglobulin antibodies are present."],["q-fcps-pat6-86","De Quervain (subacute granulomatous) thyroiditis is:",["Painful, self-limiting and follows a viral infection","Painless","Autoimmune with antibodies","Associated with fibrosis"],"Raised ESR and low radioiodine uptake are seen."],["q-fcps-pat6-87","Graves disease is characterised by:",["TSH receptor stimulating antibodies","Anti-TPO only","TSH-secreting tumour","Iodine deficiency"],"Exophthalmos and pretibial myxoedema are unique features."],["q-fcps-pat6-88","Primary hyperparathyroidism is most commonly caused by:",["A single parathyroid adenoma","Parathyroid hyperplasia","Carcinoma","Renal failure"],"Bones, stones, groans and psychiatric overtones."],["q-fcps-pat6-89","Osteitis fibrosa cystica (brown tumour) is seen in:",["Hyperparathyroidism","Hypoparathyroidism","Paget disease","Osteoporosis"],"Subperiosteal bone resorption of the phalanges is characteristic."],["q-fcps-pat6-90","Which MEN syndrome includes medullary thyroid carcinoma and pheochromocytoma?",["MEN 2A","MEN 1","MEN 2B","MEN 4"],"MEN 1 comprises tumours of the parathyroid, pancreas and pituitary (the three Ps)."],["q-fcps-pat6-91","Pheochromocytoma follows the rule of 10s, in which approximately:",["10 percent are malignant, bilateral or extra-adrenal","50 percent are malignant","90 percent are bilateral","90 percent are extra-adrenal"],"Urinary metanephrines and VMA are raised."],["q-fcps-pat6-92","Waterhouse-Friderichsen syndrome is adrenal haemorrhage associated with:",["Meningococcal septicaemia","Tuberculosis","Autoimmune disease","Metastasis"],"Autoimmune adrenalitis is the commonest cause of Addison disease in the West; tuberculosis is common in developing countries."],["q-fcps-pat6-93","Conn syndrome is due to:",["Aldosterone-secreting adenoma, with hypertension and hypokalaemia","Cortisol excess","ACTH excess","Catecholamine excess"],"Renin is low."],["q-fcps-pat6-94","The most common cause of Cushing syndrome overall is:",["Exogenous steroids","Pituitary adenoma","Adrenal adenoma","Ectopic ACTH"],"Cushing disease refers to a pituitary ACTH-secreting tumour."]];
